TLM.f("Tempora/Pent01-0r",{"officium":"Dominica Sanctissimæ Trinitatis","rule":["Gloria","Credo","Prefatio=Trinitate"],"sections":{"Introitus":[{"k":"ref","la":"Tob 12:6"},{"k":"text","la":"Benedícta sit sancta Trínitas atque indivísa Unitas: confitébimur ei, quia fecit nobíscum misericórdiam suam."},{"k":"ref","la":"Ps 8:2"},{"k":"text","la":"Dómine, Dóminus noster, quam admirábile est nomen tuum in univérsa terra!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Benedícta sit sancta Trínitas atque indivísa Unitas: confitébimur ei, quia fecit nobíscum misericórdiam suam."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui dedísti fámulis tuis in confessióne veræ fídei, ætérnæ Trinitátis glóriam agnóscere, et in poténtia majestátis adoráre Unitátem: quǽsumus; ut, ejúsdem fídei firmitáte, ab ómnibus semper muniámur advérsis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 11:33-36"},{"k":"text","la":"O altitúdo divitiárum sapiéntiæ et sciéntiæ Dei: quam incomprehensibília sunt judícia ejus, et investigábiles viæ ejus! Quis enim cognovit sensum Dómini? Aut quis consiliárius ejus fuit? Aut quis prior dedit illi, et retribuétur ei? Quóniam ex ipso et per ipsum et in ipso sunt ómnia: ipsi glória in sǽcula. Amen."}],"Graduale":[{"k":"ref","la":"Dan 3:55-56"},{"k":"text","la":"Benedíctus es, Dómine, qui intuéris abýssos, et sedes super Chérubim,"},{"k":"text","la":"Benedíctus es, Dómine, in firmaménto cæli, et laudábilis in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Dan 3:52"},{"k":"text","la":"Benedíctus es, Dómine, Deus patrum nostrórum, et laudábilis in sǽcula. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 28:18-20"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Data est mihi omnis potéstas in cœlo et in terra. Eúntes ergo docéte omnes gentes, baptizántes eos in nómine Patris, et Fílii, et Spíritus Sancti: docéntes eos serváre ómnia, quæcúmque mandávi vobis. Et ecce, ego vobíscum sum ómnibus diébus usque ad consummatiónem sǽculi."}],"Offertorium":[{"k":"ref","la":"Tob 12:6"},{"k":"text","la":"Benedíctus sit Deus Pater, unigenitúsque Dei Fílius, Sanctus quoque Spíritus: quia fecit nobíscum misericórdiam suam."}],"Secreta":[{"k":"text","la":"Sanctífica, quǽsumus, Dómine, Deus noster, per tui sancti nóminis invocatiónem, hujus oblatiónis hóstiam: et per eam nosmetípsos tibi pérfice munus ætérnum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Tob 12:6"},{"k":"text","la":"Benedícimus Deum cœli et coram ómnibus vivéntibus confitébimur ei: quia fecit nobíscum misericórdiam suam."}],"Postcommunio":[{"k":"text","la":"Profíciat nobis ad salútem córporis et ánimæ, Dómine, Deus noster, hujus sacraménti suscéptio: et sempitérnæ sanctæ Trinitátis ejusdémque indivíduæ Unitátis conféssio."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Dominicam I post Pentecosten"},{"k":"text","la":"Deus, in te sperántium fortitúdo, adésto propítius invocatiónibus nostris: et, quia sine te nihil potest mortális infírmitas, præsta auxílium grátiæ tuæ; ut, in exsequéndis mandátis tuis, et voluntáte tibi et actióne placeámus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Dominica"},{"k":"text","la":"Hóstias nostras, quǽsumus, Dómine, tibi dicátas placátus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Dominica"},{"k":"text","la":"Tantis, Dómine, repléti munéribus: præsta, quǽsumus; ut et salutária dona capiámus, et a tua numquam laude cessémus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6269b2d22cc48d78":{"t":"Tob 12, 6, Ps 8, 2\n(Tob 12, 6) Blagoslovljeno budi sveto Trojstvo i nerazdjeljivo jedinstvo. Hvalimo ga, jer nam iskaza svoje milosrđe. (Ps 8, 2) Gospodine, Gospodine naš, kako li je divno tvoje ime po svoj zemlji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Tob 12, 6) Blagoslovljeno budi sveto Trojstvo i nerazdjeljivo jedinstvo. Hvalimo ga, jer nam iskaza svoje milosrđe."},"d3128f47ca3173f2":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si svojim slugama dao da u ispovijedanju prave vjere spoznaju slavu vječnoga Trojstva i da se u silnom veličanstvu poklone jedinstvu, molimo da se po čvrstoći iste vjere od svih nezgoda uvijek obranimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0a1a3b39b92c6f96":{"t":"Rim 11, 33-36\nČitanje Poslanice bl. Pavla apostola Rimljanima. O dubino bogatstva, mudrosti i znanja Božjega! Kako su nedokučivi njegovi sudovi i neistraživi putovi. Jer, tko zna misao Gospodnju? Ili tko mu je bio savjetnik? Ili tko je njemu prije što dao da bi trebalo da mu uzvrati? Sve je od njega i po njemu i u njemu. Njemu slava u vijeke. Amen."},"a5dc7b894482ec7c":{"t":"Dn 3, 55-56\nBlagoslovljen si, Gospodine, koji motriš bezdane i stoluješ nad kerubinima. Blagoslovljen si, Gospodine, na svodu nebeskom i vrijedan hvale u vijeke.\n\nDn 3, 52\n<i>Aleluja</i>, <i>aleluja</i>.\nBlagoslovljen si, Gospodine Bože otaca naših, i vrijedan hvale u vijeke. <i>Aleluja</i>."},"8c35c131b052edc5":{"t":"Mt 28, 18-20\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Dana mi je sva vlast na nebu i na zemlji. Pođite stoga i učite sve narode. Krštavajte ih u ime Oca i Sina i Duha Svetoga. Učite ih da vrše sve zapovijedi koje sam vam dao. I evo, ja sam s vama u sve dane do svršetka svijeta."},"ae33f17f24f527e7":{"t":"Tob 12, 6\nBlagoslovljen Bog Otac i jedinorođeni Božji Sin i Duh Sveti, jer nam iskaza svoje milosrđe."},"c64fb97e46ff2977":{"t":"Posveti, molimo, Gospodine Bože naš, po zazivanju tvojega svetog imena ovaj žrtveni dar, a po njemu i nas učini tebi vječnim prinosom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"ae72cb6a4d2cffa3":{"t":"Tob 12, 6\nBlagoslivljajmo Boga nebeskoga i slavimo ga pred svim živim bićima, jer nam iskaza svoje milosrđe."},"4a9c0067b9c10558":{"t":"<i>Pomolimo se</i>.\nBilo nam na spas tijela i duše, Gospodine Bože naš, primanje ovog otajstva i ispovijedanje vječnoga svetog Trojstva i njegova nedjeljivog jedinstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
